from pathlib import Path

path = Path('.github/workflows/build-living-kingdoms.yml')
text = path.read_text(encoding='utf-8')
start_marker = '      - name: Graphical UI and client startup audit\n'
end_marker = '      - name: Package internal alpha.12 checkpoint\n'
start = text.find(start_marker)
end = text.find(end_marker, start)
if start < 0 or end < 0:
    raise SystemExit('canonical client audit step boundaries not found')

replacement = '''      - name: Graphical UI and client startup audit\n        working-directory: ${{ env.PROJECT_DIR }}\n        shell: bash\n        env:\n          LIBGL_ALWAYS_SOFTWARE: '1'\n        run: |\n          set -euo pipefail\n          log=../../logs/client-smoke.log\n          : > "$log"\n\n          # Hosted images normally already contain the graphical smoke prerequisites. Do not\n          # perform an unbounded apt refresh on every canonical run; only install when missing,\n          # and bound both network/package operations so CI cannot hang before runClient starts.\n          need_graphics=0\n          command -v xvfb-run >/dev/null 2>&1 || need_graphics=1\n          ldconfig -p 2>/dev/null | grep -Fq 'libGL.so.1' || need_graphics=1\n          if [ "$need_graphics" -eq 1 ]; then\n            sudo timeout --signal=TERM --kill-after=10s 120s \\\n              apt-get -o Acquire::Retries=2 -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 update -qq\n            sudo timeout --signal=TERM --kill-after=10s 120s \\\n              apt-get -o Acquire::Retries=2 -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 \\\n              install -y --no-install-recommends xvfb libgl1-mesa-dri >/dev/null\n          fi\n          command -v xvfb-run >/dev/null\n\n          # The in-game diagnostics complete by client tick 216. Run the whole Xvfb/Gradle\n          # launcher beneath a dedicated session, watch the authoritative PASS markers, then\n          # terminate every descendant once proof is complete. This avoids Gradle/Xvfb orphan\n          # processes holding the Actions step open after the Minecraft JVM has already exited.\n          setsid bash -c \"exec xvfb-run -a -s '-screen 0 1280x720x24' gradle --no-daemon runClient --stacktrace --console=plain\" \\\n            > "$log" 2>&1 &\n          client_launcher=$!\n          sleep 1\n          client_pgid="$(ps -o pgid= -p "$client_launcher" 2>/dev/null | tr -d ' ' || true)"\n          if [ -z "$client_pgid" ]; then\n            client_pgid="$client_launcher"\n          fi\n\n          outcome=timeout\n          for attempt in $(seq 1 240); do\n            if grep -Fq 'LK_CLIENT_DIAGNOSTIC_PASS screen=origin_selection fixed_erden_origin=true' "$log" \\\n              && grep -Fq 'LK_CLIENT_LOADING_DIAGNOSTIC_PASS screen=realm_loading non_pausing=true' "$log" \\\n              && grep -Fq 'LK_CLIENT_CODEX_DIAGNOSTIC_PASS screens=overview,equipment,map,skills' "$log"; then\n              outcome=pass\n              break\n            fi\n            # Do not classify a generic IllegalStateException as fatal here. Headless Linux\n            # clients legitimately emit one when OpenAL has no audio device, after which\n            # Minecraft disables sound and continues rendering. Only product-specific or\n            # graphical startup failure signatures are early-fatal.\n            if grep -Eqi 'Caught exception from Living Kingdoms|Error during client initialization|Exception in client tick loop|Rendering screen|Missing textures in model livingkingdoms|Could not initialize GLFW|Failed to create window' "$log"; then\n              outcome=fatal\n              break\n            fi\n            if ! kill -0 "$client_launcher" 2>/dev/null; then\n              outcome=client_exit\n              break\n            fi\n            sleep 1\n          done\n\n          # Close the dedicated process group regardless of outcome; PASS is defined by the\n          # graphical diagnostic markers, not by whether Gradle elects to linger afterward.\n          kill -TERM -- "-$client_pgid" 2>/dev/null || true\n          sleep 3\n          kill -KILL -- "-$client_pgid" 2>/dev/null || true\n          wait "$client_launcher" 2>/dev/null || true\n\n          # Cover the narrow race where the client exited immediately after flushing all markers.\n          if grep -Fq 'LK_CLIENT_DIAGNOSTIC_PASS screen=origin_selection fixed_erden_origin=true' "$log" \\\n            && grep -Fq 'LK_CLIENT_LOADING_DIAGNOSTIC_PASS screen=realm_loading non_pausing=true' "$log" \\\n            && grep -Fq 'LK_CLIENT_CODEX_DIAGNOSTIC_PASS screens=overview,equipment,map,skills' "$log"; then\n            outcome=pass\n          fi\n\n          cat "$log"\n          echo "CLIENT_AUDIT_OUTCOME=$outcome"\n          test "$outcome" = pass\n          grep -F 'LK_CLIENT_DIAGNOSTIC_PASS screen=origin_selection fixed_erden_origin=true' "$log"\n          grep -F 'LK_CLIENT_LOADING_DIAGNOSTIC_PASS screen=realm_loading non_pausing=true' "$log"\n          grep -F 'LK_CLIENT_CODEX_DIAGNOSTIC_PASS screens=overview,equipment,map,skills' "$log"\n          if grep -Eqi 'Caught exception from Living Kingdoms|Error during client initialization|Exception in client tick loop|Rendering screen|Missing textures in model livingkingdoms' "$log"; then\n            exit 1\n          fi\n\n'''

patched = text[:start] + replacement + text[end:]
if patched == text:
    print('Living Kingdoms canonical client watchdog already current')
else:
    path.write_text(patched, encoding='utf-8')
    print('Living Kingdoms canonical graphical client audit now ignores expected headless audio exceptions')
